channels = [
    {"name": "Cobly", "videos": 96, "views": 412000, "subscribers": 188000},
    {"name": "Pluma Waves", "videos": 41, "views": 88000, "subscribers": 37},
    {"name": "Gildo", "videos": 22, "views": 15400, "subscribers": 1240}
]

def total_of(rows, field):
    total = 0
    for channel in rows:
        total = total + channel[field]
    return total

def names_under(rows, limit):
    found = []
    for channel in rows:
        if channel["subscribers"] < limit:
            found.append(channel["name"])
    return found

print("views:", total_of(channels, "views"))
print("under:", names_under(channels, 1000))
print("videos:", total_of(channels, "videos"))
